[
  {
    "qa_id": "qa-001",
    "question": "database × web: データベースの仕様は?",
    "answer": "SQLite ファイル 1 個 (todo.db)。テーブルは todos と api_tokens。起動時にスキーマを冪等作成し、マイグレーションは単調増加の SQL 版数で管理する。",
    "ops": [{"action": "confirm", "category": "database", "platform": "web", "serves_goals": ["G1", "G3", "G4"]}]
  },
  {
    "qa_id": "qa-002",
    "question": "auth × web: 認証方式の仕様は?",
    "answer": "単一利用者向けの bearer token 認証。token は初回起動時にローカル生成し、ハッシュ化して保存する。全 TODO エンドポイントで必須、未認証は 401。",
    "ops": [{"action": "confirm", "category": "auth", "platform": "web", "serves_goals": ["G2"]}]
  },
  {
    "qa_id": "qa-003",
    "question": "ui-ux × web: UI/UX の仕様は?",
    "answer": "UI は持たない。API の使い勝手として、エラー応答を {\"error\": {\"code\", \"message\"}} に統一し、OpenAPI 定義を /openapi.json でローカル提供する。",
    "ops": [{"action": "confirm", "category": "ui-ux", "platform": "web", "serves_goals": ["G2", "G4"]}]
  },
  {
    "qa_id": "qa-004",
    "question": "security × web: セキュリティの仕様は?",
    "answer": "localhost (127.0.0.1) バインド固定、外向き通信なし、token はハッシュ保存、入力は schema 検証、SQL は必ずパラメータバインド。",
    "ops": [{"action": "confirm", "category": "security", "platform": "web", "serves_goals": ["G1", "G2"]}]
  },
  {
    "qa_id": "qa-005",
    "question": "infrastructure × web: インフラの仕様は?",
    "answer": "常駐ミドルウェアなし。1 コマンド起動、データはファイル 1 個。バックアップはそのファイルのコピー。",
    "ops": [{"action": "confirm", "category": "infrastructure", "platform": "web", "serves_goals": ["G1", "G4"]}]
  },
  {
    "qa_id": "qa-006",
    "question": "backend × web: バックエンドの仕様は?",
    "answer": "Python の ASGI/WSGI ベース REST API。/todos の CRUD と完了操作、/health。層は router / service / repository の 3 層。",
    "ops": [{"action": "confirm", "category": "backend", "platform": "web", "serves_goals": ["G2", "G3"]}]
  },
  {
    "qa_id": "qa-007",
    "question": "frontend × web: フロントエンドの仕様は?",
    "answer": "専用フロントエンドを実装しない。動作確認は OpenAPI 定義と HTTP クライアント (curl 等) で行う。",
    "ops": [{"action": "confirm", "category": "frontend", "platform": "web", "serves_goals": ["G4"]}]
  },
  {
    "qa_id": "qa-008",
    "question": "maintenance-ops × web: 保守運用の仕様は?",
    "answer": "構造化ログを標準出力へ、/health で稼働確認、バックアップ/復旧手順を README 化。監視の外部送信は行わない。",
    "ops": [{"action": "confirm", "category": "maintenance-ops", "platform": "web", "serves_goals": ["G3", "G4"]}]
  },
